import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"系统级脚本能力解析","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/系统级脚本能力解析.md","filePath":"脚本系统/专题研究/系统级脚本能力解析.md","lastUpdated":1777893104000}'),h={name:"脚本系统/专题研究/系统级脚本能力解析.md"};function d(o,l,c,n,t,s){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="系统级脚本能力解析" tabindex="-1">系统级脚本能力解析 <a class="header-anchor" href="#系统级脚本能力解析" aria-label="Permalink to “系统级脚本能力解析”">​</a></h1><ul><li>分类：脚本</li><li>子系统：系统脚本 / 地图切换 / 广播 / 声音 / 计时器 / 全局流程</li><li>关键词标签：系统脚本, 地图切换, 地图广播, 播放音效, BGM, 计时器, 游戏胜利, 结束本局</li><li>来源类型：脚本界面截图主题整理</li><li>证据等级：截图直接证据 + 人工归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li><li>来源截图编号：215405, 215557, 215620, 215621, 215622, 215623, 215624, 215625</li><li>对应 OCR 文档：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li></ul><p>本文件基于 <code>资料/基础写脚本界面截图/</code> 中系统作用域相关截图整理，目标是把“系统”分类下可见的脚本能力拆成更细的知识专题，方便检索与教学。</p><blockquote><p>说明：内容来自截图 OCR 与人工修正，个别术语仍可能存在识别误差，但整体结构已经较明确。</p></blockquote><h2 id="_1-系统作用域的分类结构" tabindex="-1">1. 系统作用域的分类结构 <a class="header-anchor" href="#_1-系统作用域的分类结构" aria-label="Permalink to “1. 系统作用域的分类结构”">​</a></h2><p>从多张截图可确认，在“执行系统 ... 并等待结束”这一类脚本选择界面中，系统能力至少细分为：</p><ul><li>单机</li><li>联机</li><li>地图</li><li>声音</li><li>计时器</li><li>脚本</li></ul><p>这说明系统级脚本并不是一个简单的扁平列表，而是进一步按功能域组织。</p><h3 id="知识意义" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义" aria-label="Permalink to “知识意义”">​</a></h3><ul><li>单机 / 联机：说明系统逻辑会区分本地玩法与多人玩法。</li><li>地图：说明部分全局场景控制虽然属于地图相关，但也可从系统入口统一调度。</li><li>声音：音频控制被视作系统能力而不是单纯物体属性。</li><li>计时器：表明时间流程控制有专门模块。</li><li>脚本：说明系统作用域下还可能有更高层的脚本事件或广播接口。</li></ul><hr><h2 id="_2-已确认的系统流程控制脚本" tabindex="-1">2. 已确认的系统流程控制脚本 <a class="header-anchor" href="#_2-已确认的系统流程控制脚本" aria-label="Permalink to “2. 已确认的系统流程控制脚本”">​</a></h2><p>从截图 <code>Screenshot_20260417_215620.jpg</code> 与 <code>Screenshot_20260417_215621.jpg</code> 可确认：</p><ul><li>游戏胜利</li><li>游戏失败</li><li>重新开始</li><li>结束本局</li></ul><h3 id="结构理解" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解" aria-label="Permalink to “结构理解”">​</a></h3><p>这些脚本块直接作用于整局流程，而不是单个物体。</p><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to “适用场景”">​</a></h3><ul><li>胜负判定后立即结算</li><li>关卡失败后重开</li><li>自定义流程脚本控制对局终止</li><li>单机或联机模式中的全局结果判定</li></ul><h3 id="知识意义-1" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-1" aria-label="Permalink to “知识意义”">​</a></h3><p>这说明创游脚本系统允许创作者在积木层直接操控“游戏状态机”的关键节点，而不必完全依赖默认流程。</p><hr><h2 id="_3-地图相关系统脚本" tabindex="-1">3. 地图相关系统脚本 <a class="header-anchor" href="#_3-地图相关系统脚本" aria-label="Permalink to “3. 地图相关系统脚本”">​</a></h2><p>从截图 <code>Screenshot_20260417_215622.jpg</code> 可识别：</p><ul><li>切换地图</li><li>向地图发送广播</li></ul><h3 id="结构理解-1" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-1" aria-label="Permalink to “结构理解”">​</a></h3><p>这两项能力说明系统层至少支持：</p><ol><li>关卡/地图切换</li><li>向地图层广播消息</li></ol><h3 id="可能意义" tabindex="-1">可能意义 <a class="header-anchor" href="#可能意义" aria-label="Permalink to “可能意义”">​</a></h3><ul><li><code>切换地图</code>：用于关卡跳转、场景迁移、章节推进。</li><li><code>向地图发送广播</code>：用于把全局事件交给地图层逻辑处理，例如： <ul><li>触发刷怪</li><li>切换背景</li><li>改变地图环境参数</li><li>开始或结束某段脚本流程</li></ul></li></ul><h3 id="和-ui-物体脚本的关系" tabindex="-1">和 UI / 物体脚本的关系 <a class="header-anchor" href="#和-ui-物体脚本的关系" aria-label="Permalink to “和 UI / 物体脚本的关系”">​</a></h3><p>地图广播可以作为物体脚本与地图逻辑之间的桥梁：</p><ul><li>物体触发事件</li><li>系统或地图接收广播</li><li>地图层统一组织更高层逻辑</li></ul><hr><h2 id="_4-声音系统脚本" tabindex="-1">4. 声音系统脚本 <a class="header-anchor" href="#_4-声音系统脚本" aria-label="Permalink to “4. 声音系统脚本”">​</a></h2><p>从截图 <code>Screenshot_20260417_215623.jpg</code> 可识别：</p><ul><li>播放音效</li><li>播放 BGM</li><li>停止 BGM</li></ul><h3 id="结构理解-2" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-2" aria-label="Permalink to “结构理解”">​</a></h3><p>这说明音频系统至少区分：</p><ul><li>短时音效（音效）</li><li>背景音乐（BGM）</li></ul><h3 id="可能用法" tabindex="-1">可能用法 <a class="header-anchor" href="#可能用法" aria-label="Permalink to “可能用法”">​</a></h3><ul><li><code>播放音效</code>：攻击、拾取、按钮点击、命中反馈等短音频。</li><li><code>播放 BGM</code>：进入地图、进入战斗、剧情阶段切换时播放背景音乐。</li><li><code>停止 BGM</code>：结束战斗、剧情切换、进入结算画面时停止当前背景音乐。</li></ul><h3 id="知识意义-2" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-2" aria-label="Permalink to “知识意义”">​</a></h3><p>这说明声音控制可以在系统层全局调度，而不是必须绑定到具体物体，适合管理整局氛围与阶段节奏。</p><hr><h2 id="_5-计时器系统脚本" tabindex="-1">5. 计时器系统脚本 <a class="header-anchor" href="#_5-计时器系统脚本" aria-label="Permalink to “5. 计时器系统脚本”">​</a></h2><p>从截图 <code>Screenshot_20260417_215624.jpg</code> 可识别：</p><ul><li>开始计时</li><li>停止计时</li></ul><h3 id="结构理解-3" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-3" aria-label="Permalink to “结构理解”">​</a></h3><p>这意味着创游中至少存在一个可由脚本控制的系统级计时模块。</p><h3 id="可能应用" tabindex="-1">可能应用 <a class="header-anchor" href="#可能应用" aria-label="Permalink to “可能应用”">​</a></h3><ul><li>限时挑战</li><li>倒计时任务</li><li>生存模式计时</li><li>竞速玩法</li><li>波次刷怪间隔控制</li></ul><h3 id="知识意义-3" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-3" aria-label="Permalink to “知识意义”">​</a></h3><p>计时器被单独列出，说明时间控制不是零散附着在别的脚本块里，而是一个相对明确的子系统。后续若恢复原图并继续 OCR 到更多截图，可能还能发现：</p><ul><li>获取当前计时值</li><li>重置计时</li><li>暂停计时</li><li>计时结束事件</li></ul><hr><h2 id="_6-并等待结束-的流程语义" tabindex="-1">6. “并等待结束”的流程语义 <a class="header-anchor" href="#_6-并等待结束-的流程语义" aria-label="Permalink to “6. “并等待结束”的流程语义”">​</a></h2><p>多张系统脚本截图顶部都出现：</p><ul><li><code>执行系统 ... 并等待结束</code></li></ul><h3 id="可推断出的机制" tabindex="-1">可推断出的机制 <a class="header-anchor" href="#可推断出的机制" aria-label="Permalink to “可推断出的机制”">​</a></h3><p>这说明系统脚本块可能支持两种语义：</p><ol><li>立即触发，不等待完成</li><li>触发后等待该动作完成，再执行后续脚本</li></ol><h3 id="对复杂逻辑的意义" tabindex="-1">对复杂逻辑的意义 <a class="header-anchor" href="#对复杂逻辑的意义" aria-label="Permalink to “对复杂逻辑的意义”">​</a></h3><p>这种设计对以下场景很重要：</p><ul><li>等待切图完成后再生成玩家</li><li>等待某段系统流程结束后再结算</li><li>等待 BGM / 过渡流程处理后再进入下一个阶段</li></ul><p>虽然截图里还不能确认每个系统动作是否都真的“可等待”，但从界面表现看，系统块至少支持这种统一的时序接口。</p><hr><h2 id="_7-系统级脚本与对象级脚本的分工" tabindex="-1">7. 系统级脚本与对象级脚本的分工 <a class="header-anchor" href="#_7-系统级脚本与对象级脚本的分工" aria-label="Permalink to “7. 系统级脚本与对象级脚本的分工”">​</a></h2><p>结合脚本界面其他截图，可以初步把分工理解为：</p><h3 id="对象级脚本更适合" tabindex="-1">对象级脚本更适合 <a class="header-anchor" href="#对象级脚本更适合" aria-label="Permalink to “对象级脚本更适合”">​</a></h3><ul><li>控制单个物体</li><li>控制子物体</li><li>播放动画</li><li>发送普通广播</li><li>销毁自身</li></ul><h3 id="地图级脚本更适合" tabindex="-1">地图级脚本更适合 <a class="header-anchor" href="#地图级脚本更适合" aria-label="Permalink to “地图级脚本更适合”">​</a></h3><ul><li>生成物体</li><li>生成特效</li><li>设置背景颜色</li><li>地图层广播</li></ul><h3 id="系统级脚本更适合" tabindex="-1">系统级脚本更适合 <a class="header-anchor" href="#系统级脚本更适合" aria-label="Permalink to “系统级脚本更适合”">​</a></h3><ul><li>胜负与对局结束</li><li>地图切换</li><li>全局音频</li><li>计时器控制</li></ul><h3 id="知识意义-4" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-4" aria-label="Permalink to “知识意义”">​</a></h3><p>这有助于后续在知识库中形成“脚本职责边界”概念，避免把地图级或系统级逻辑错误地塞到单物体脚本里。</p><hr><h2 id="_8-适合-ai-rag-的关键词" tabindex="-1">8. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_8-适合-ai-rag-的关键词" aria-label="Permalink to “8. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>系统脚本</li><li>单机</li><li>联机</li><li>地图</li><li>声音</li><li>计时器</li><li>脚本</li><li>游戏胜利</li><li>游戏失败</li><li>重新开始</li><li>结束本局</li><li>切换地图</li><li>向地图发送广播</li><li>播放音效</li><li>播放BGM</li><li>停止BGM</li><li>开始计时</li><li>停止计时</li><li>并等待结束</li></ul><hr><h2 id="_9-后续可继续验证的问题" tabindex="-1">9. 后续可继续验证的问题 <a class="header-anchor" href="#_9-后续可继续验证的问题" aria-label="Permalink to “9. 后续可继续验证的问题”">​</a></h2><ol><li>系统计时器是否支持倒计时与读取当前时间？</li><li>联机分类下还有哪些系统脚本？</li><li><code>向地图发送广播</code> 与普通广播是否存在作用域区别？</li><li>切换地图后，局部变量 / 系统变量 / 地图变量如何保留？</li><li>声音系统是否支持暂停、恢复、淡入淡出等更多控制？</li></ol>',82)])])}const _=i(h,[["render",d]]);export{b as __pageData,_ as default};
